from svg import box, t, svg

_Q = [(140, 60, 's-card', 'THE SALESMAN', 'oversells, but refusal', 'is still safe'),
      (560, 60, 's-card', 'THE ENTHUSIAST', 'odd beliefs, open books,', 'easy exit'),
      (140, 230, 's-box-a', 'THE CON', 'theatre plus power:', 'nobody can say no'),
      (560, 230, 's-box-a', 'THE PROPHET', 'certainty plus power:', 'often the worst')]
_inner = t(340, 45, 'PERFORMS IT', 's-t') + t(760, 45, 'BELIEVES IT', 's-t')
_inner += t(70, 128, 'can be', 's-t-sm') + t(70, 150, 'checked', 's-t-sm') + t(70, 298, 'cannot be', 's-t-sm') + t(70, 320, 'checked', 's-t-sm')
for _x, _y, _c, _a, _b, _d in _Q:
    _inner += box(_x, _y, 400, 150, _c) + t(_x + 200, _y + 58, _a, 's-t-b') + t(_x + 200, _y + 92, _b, 's-t-sm') + t(_x + 200, _y + 116, _d, 's-t-sm')
_inner += t(560, 414, 'Danger runs down the grid (checks on power), not across it (belief).', 's-t-sm')
FIG = svg(1000, 430, 'Belief versus checks on power', _inner)

